def new25(ref,native,oldtexts,contractions):
 hyp=expanded_words(native['feature_text'],contractions);char,cm=alignment(ref,hyp);unused,phone,pm=phonetic_alignment(ref,hyp);oldmaps=[alignment(ref,expanded_words(t,contractions))[1]for t in oldtexts];n=len(ref);agreement=np.asarray([[float(pm[j]is not None and mm[j]is not None and phone_pair(pm[j],mm[j])[2])for mm in oldmaps]for j in range(n)])
 st=native['summary'];global10=np.asarray([st['mean_valid_token_logp'],st['entropy'],st['blank_probability'],st['probability_margin'],st['duration_mean']/4,st['nonblank_count']/n,len(hyp)/n,float(st['valid_token_count']==0),float(st['EOS']),float(st['cap_hit'])]);out=np.c_[char,phone,agreement,np.repeat(global10[None,:],n,axis=0)];assert out.shape==(n,25)and np.isfinite(out).all();return out
